-- Fitur tambahan bot_old.js; aman dijalankan berulang dan tidak menghapus data.
CREATE TABLE IF NOT EXISTS telegram_group_members (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, telegram_id VARCHAR(50) NOT NULL, phone_number VARCHAR(30) DEFAULT NULL, display_name VARCHAR(150) DEFAULT NULL, group_id VARCHAR(100) NOT NULL, group_name VARCHAR(150) DEFAULT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', joined_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, left_at DATETIME DEFAULT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (id), UNIQUE KEY uq_telegram_group_member_identity (telegram_id, group_id), KEY idx_telegram_group_member_phone (phone_number), KEY idx_telegram_group_member_status (status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
INSERT INTO bot_globals (key_name,key_value) SELECT 'WELCOME_MESSAGE','Selamat Datang {NAMA_USER}, pastikan membaca rules yang ada di dalam group, pahami dan lakukan.' WHERE NOT EXISTS (SELECT 1 FROM bot_globals WHERE key_name='WELCOME_MESSAGE');
INSERT INTO bot_globals (key_name,key_value) SELECT 'WELCOME_BACK_MESSAGE','Selamat Datang Kembali {NAMA_USER}, pastikan membaca rules yang ada di dalam group, pahami dan lakukan.' WHERE NOT EXISTS (SELECT 1 FROM bot_globals WHERE key_name='WELCOME_BACK_MESSAGE');
